  ctx.restore();
  // контур желудочков — плотный пучок, коронарные сосуды — самые яркие
  strands(body.pts, true, 7, 6, 1.7, 0.9, 12);
  strands(groove.pts, false, 2, 1.6, 1.3, 0.95, 14);
