    hb.vel[0] += (Math.random() - 0.5) * 0.35;
    hb.vel[1] += (Math.random() - 0.5) * 0.35;
    hb.pos[0] += hb.vel[0];
    hb.pos[1] += hb.vel[1];
    if (!last && dist < 9) hb.i++;
